package com.yuyutian.mytools.messaging.repository;
import com.yuyutian.mytools.messaging.model.LegacyFeedbackItem;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.Timestamp;import java.time.Instant;import java.util.*;
/** 问题反馈仓储。 */ @Repository public class SupportFeedbackRepository {private final JdbcTemplate jdbc;/** 创建仓储。 @param jdbc JDBC */ public SupportFeedbackRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 /** 查询迁移摘要。 @param legacyId 旧标识 @return 摘要 */ public String digest(long legacyId){return jdbc.query("SELECT payload_sha256 FROM support_feedback_migration WHERE legacy_id=?",(rs,row)->rs.getString(1),legacyId).stream().findFirst().orElse(null);}
 /** 保存旧反馈。 @param key 迁移键 @param item 反馈 @param digest 摘要 @param now 时间 */ public void insert(String key,LegacyFeedbackItem item,String digest,Instant now){String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO support_feedback VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,item.legacyId(),item.username(),item.email(),item.phone(),item.category(),item.title(),item.content(),item.status(),Timestamp.from(item.createdAt()),Timestamp.from(item.updatedAt()));jdbc.update("INSERT INTO support_feedback_migration VALUES (?,?,?,?,?)",item.legacyId(),key,digest,id,Timestamp.from(now));}
 /** 查询迁移摘要记录。 @param key 迁移键 @return 旧标识和摘要 */ public List<String> migrationEvidence(String key){return jdbc.query("SELECT legacy_id,payload_sha256 FROM support_feedback_migration WHERE migration_key=? ORDER BY legacy_id",(rs,row)->rs.getLong(1)+"|"+rs.getString(2),key);}
}
